export const MLXTRAN_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/mlxtran-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getMlxtranStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(MLXTRAN_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
